// A whole five-custodian ceremony, real browser code against the real binary.
//
// This is the test that proves the thing the command exists for, because it is
// the only one where both halves are the production code: the phrases are
// generated by src/key.ts exactly as a custodian's browser generates them, and
// they are sent to a `ceremony host` process over HTTP exactly as a custodian's
// browser sends them.
//
// Five claims, each asserted rather than observed:
//
//	1. No request body contains a phrase or a private key. Every byte of every
//	   request is captured and searched, including for any run of six BIP-39
//	   words, so a partial leak fails too.
//	2. The address the browser derives is the address Go derives. The host
//	   re-derives it from the public key and refuses a mismatch, so a submission
//	   the host accepts is a submission the two sides agreed on.
//	3. A submission with a swapped address is refused.
//	4. An instance refuses to attest when its own address is absent from the
//	   computed group.
//	5. Two instances compute an identical fingerprint.
//
// Skipped unless CEREMONY_HOST_BIN names a built binary, following the same
// pattern as tools/ceremony/live_test.go: it needs a Go toolchain to produce one,
// and the client CI job has only node.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn, type ChildProcess } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { deriveKey, identityOf, newPhrase, normalisePhrase, sign, signSubmission } from './key.ts';
import { assembleGroup, missingFrom, presence, type Assembled } from './group.ts';
import { attestationCanonical, toBase64, type Attestation, type CeremonyParams, type Submission } from './wire.ts';

const BINARY = process.env.CEREMONY_HOST_BIN;

const wordlist = new Set(
  (
    JSON.parse(
      readFileSync(fileURLToPath(new URL('../../../testdata/vectors/ceremony.json', import.meta.url)), 'utf8'),
    ) as { custodians: Array<{ phrase: string }> }
  ).custodians.flatMap((c) => c.phrase.split(' ')),
);

const ROSTER = ['A. Okafor', 'Chipo & Sons <Trust>', 'Naledi Ngũgĩ', 'Bank of Yamale', 'J. Mwangi'];

type Recorded = { path: string; body: string };

// Every request the client makes, captured. The assertions run over all of them
// at the end rather than one at a time, so a body that leaked on a step nobody
// thought about still fails.
const sent: Recorded[] = [];

async function request(base: string, path: string, token: string, body?: unknown): Promise<Response> {
  const encoded = body === undefined ? undefined : JSON.stringify(body);
  if (encoded !== undefined) sent.push({ path, body: encoded });
  return fetch(`${base}${path}`, {
    method: encoded === undefined ? 'GET' : 'POST',
    headers: {
      'X-Ceremony-Token': token,
      ...(encoded === undefined ? {} : { 'Content-Type': 'application/json' }),
    },
    body: encoded,
    cache: 'no-store',
  });
}

async function json<T>(response: Response): Promise<T> {
  const text = await response.text();
  if (!response.ok) throw new Error(`${response.status}: ${text}`);
  return JSON.parse(text) as T;
}

type HostState = {
  params: CeremonyParams;
  custodians: Array<{ name: string; link?: string; phase: string }>;
  submissions: Submission[];
  ready: boolean;
  bundle_hash: string;
};

type Started = { process: ChildProcess; base: string; coordinator: string; bundleHash: string };

async function startHost(): Promise<Started> {
  const port = 18000 + Math.floor(Math.random() * 2000);
  const out = mkdtempSync(join(tmpdir(), 'ceremony-rehearsal-'));
  const child = spawn(
    BINARY as string,
    ['host', '--port', String(port), '--public-url', `http://127.0.0.1:${port}/ceremony/`, '--out', out],
    { stdio: ['ignore', 'pipe', 'pipe'] },
  );

  let stdout = '';
  const ready = new Promise<{ coordinator: string; bundleHash: string }>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`the host did not print a coordinator link:\n${stdout}`)), 20000);
    child.stdout?.on('data', (chunk: Buffer) => {
      stdout += chunk.toString();
      const link = /(http:\/\/127\.0\.0\.1:\d+\/ceremony\/\?t=[A-Za-z0-9_-]+)/.exec(stdout);
      const hash = /^ {2}([0-9a-f]{64})$/m.exec(stdout);
      if (link && hash) {
        clearTimeout(timer);
        resolve({ coordinator: link[1] as string, bundleHash: hash[1] as string });
      }
    });
    child.on('error', reject);
    child.on('exit', (code) => reject(new Error(`the host exited with ${code}:\n${stdout}`)));
  });

  const { coordinator, bundleHash } = await ready;
  return { process: child, base: `http://127.0.0.1:${port}/ceremony/`, coordinator, bundleHash };
}

function tokenOf(link: string): string {
  return new URL(link).searchParams.get('i') ?? new URL(link).searchParams.get('t') ?? '';
}

// longestMnemonicRun finds six or more consecutive words from the phrases in
// play.
//
// Six, not one: single BIP-39 words appear in ordinary prose ("art", "record",
// "gather"), and a message containing one is not a leak. Six in a row is not
// something prose produces and is something a leaked phrase always contains.
function mnemonicRun(text: string): string | null {
  const words = text.toLowerCase().split(/[^a-z]+/);
  let run: string[] = [];
  for (const word of words) {
    if (wordlist.has(word)) {
      run.push(word);
      if (run.length >= 6) return run.join(' ');
    } else {
      run = [];
    }
  }
  return null;
}

test('a hosted ceremony runs five custodians without the coordinator ever seeing a phrase', async (t) => {
  if (!BINARY) {
    t.skip('set CEREMONY_HOST_BIN to the built ceremony binary to run the hosted rehearsal');
    return;
  }

  const host = await startHost();
  const coordinatorToken = tokenOf(host.coordinator);
  try {
    let state = await json<HostState>(
      await request(host.base, 'api/coordinator/setup', coordinatorToken, {
        ceremony: 'Yamale foundation, hosted rehearsal',
        chain_id: 'yamale-1',
        threshold: 3,
        custodians: ROSTER,
        policy_seq: 1,
        voting_period: '168h0m0s',
      }),
    );
    assert.equal(state.custodians.length, ROSTER.length);

    const links = new Map(state.custodians.map((c) => [c.name, tokenOf(c.link as string)]));
    const keys = new Map<string, ReturnType<typeof deriveKey>>();
    const phrases = new Map<string, string>();

    for (const name of ROSTER) {
      const token = links.get(name) as string;
      await json(await request(host.base, 'api/invite/opened', token, {}));
      await json(await request(host.base, 'api/invite/generated', token, {}));

      // Generated here, in the client code, exactly as the browser does it.
      const phrase = newPhrase();
      phrases.set(name, phrase);
      assert.equal(normalisePhrase(phrase).split(' ').length, 24);

      const key = deriveKey(phrase, 0);
      keys.set(name, key);

      // Claim 2: the host re-derives the address from the public key and refuses
      // any mismatch, so a submission it accepts is one where the browser's
      // derivation and Go's agreed. An accepted submission IS the assertion.
      const identity = identityOf(name, key, new Date());
      assert.equal(identity.address, key.address);
      const response = await request(
        host.base,
        'api/invite/submission',
        token,
        signSubmission(state.params.ceremony_id, identity, key.priv),
      );
      assert.equal(response.status, 200, `${name}: ${await response.text()}`);
    }

    // Claim 3: a swapped address, on a submission whose signature is otherwise
    // perfect. This is the one attack a relay could mount without breaking a
    // signature, and every later check reads the address field.
    {
      const name = ROSTER[0] as string;
      const key = keys.get(name) as ReturnType<typeof deriveKey>;
      const other = keys.get(ROSTER[1] as string) as ReturnType<typeof deriveKey>;
      const identity = identityOf(name, key, new Date());
      const submission = signSubmission(state.params.ceremony_id, identity, key.priv);
      submission.identity.address = other.address;
      const response = await request(host.base, 'api/invite/submission', links.get(name) as string, submission);
      assert.equal(response.status, 400);
      assert.match(await response.text(), /claims address/);
    }

    // Two independent instances, each computing the group for itself from the
    // relayed set. This is what five browsers do.
    const relayed = await json<{ submissions: Submission[]; waiting: string[] }>(
      await request(host.base, 'api/invite', links.get(ROSTER[0] as string) as string),
    );
    assert.equal(relayed.waiting.length, 0, missingFrom(state.params, relayed.submissions));

    const first = assembleGroup(state.params, relayed.submissions);
    const second = assembleGroup(state.params, [...relayed.submissions].reverse());

    // Claim 5.
    assert.equal(second.fingerprint, first.fingerprint);
    assert.equal(second.genesis, first.genesis);
    assert.equal(second.policy_address, first.policy_address);

    // Claim 4: an instance handed a group its own key is not in refuses. Built by
    // dropping one custodian, which is exactly the shape a relay that excluded
    // somebody would produce — internally consistent, and wrong.
    {
      const dropped = ROSTER[2] as string;
      const key = keys.get(dropped) as ReturnType<typeof deriveKey>;
      const shortParams: CeremonyParams = {
        ...state.params,
        custodians: state.params.custodians.filter((name) => name !== dropped),
      };
      const substituted: Assembled = assembleGroup(
        shortParams,
        relayed.submissions.filter((s) => s.identity.name !== dropped),
      );
      assert.notEqual(substituted.fingerprint, first.fingerprint);
      assert.throws(
        () => presence(substituted, key.address, key.fingerprint),
        /YOUR KEY IS NOT IN THIS GROUP/,
      );
      // And presence passes on the real group, so the refusal above is the check
      // working rather than the check always failing.
      presence(first, key.address, key.fingerprint);
    }

    for (const name of ROSTER) {
      const key = keys.get(name) as ReturnType<typeof deriveKey>;
      presence(first, key.address, key.fingerprint);
      const attestation: Attestation = {
        ceremony_id: state.params.ceremony_id,
        name,
        address: key.address,
        group_fingerprint: first.fingerprint,
        policy_address: first.policy_address,
        transcription_verified: true,
        restore_drill_passed: true,
        envelope_sealed: true,
        virtualised: false,
        signed_at: `${new Date().toISOString().slice(0, 19)}Z`,
      };
      const response = await request(host.base, 'api/invite/attestation', links.get(name) as string, {
        attestation,
        pubkey: { '@type': '/cosmos.crypto.secp256k1.PubKey', key: toBase64(key.pub) },
        signature: toBase64(sign(attestationCanonical(attestation), key.priv)),
      });
      assert.equal(response.status, 200, `${name}: ${await response.text()}`);
    }

    state = await json<HostState>(await request(host.base, 'api/coordinator/state', coordinatorToken));
    for (const custodian of state.custodians) {
      assert.equal(custodian.phase, 'attested', custodian.name);
    }

    // Claim 1, over every request made above.
    assert.ok(sent.length >= 20, `only ${sent.length} bodies were captured, so this would pass vacuously`);
    for (const recorded of sent) {
      const lower = recorded.body.toLowerCase();
      for (const [name, phrase] of phrases) {
        assert.ok(!lower.includes(phrase.toLowerCase()), `${name}'s phrase reached ${recorded.path}`);
      }
      for (const [name, key] of keys) {
        assert.ok(!recorded.body.includes(toBase64(key.priv)), `${name}'s private key reached ${recorded.path}`);
        const hex = Array.from(key.priv, (b) => b.toString(16).padStart(2, '0')).join('');
        assert.ok(!lower.includes(hex), `${name}'s private key reached ${recorded.path} in hex`);
      }
      const run = mnemonicRun(recorded.body);
      assert.equal(run, null, `a run of BIP-39 words reached ${recorded.path}: ${run}`);
    }

    // The hash the host printed is the hash of the bundle it serves, and it is
    // what the page shows the custodian. A mismatch would make the published
    // value meaningless.
    assert.match(host.bundleHash, /^[0-9a-f]{64}$/);
    assert.equal(state.bundle_hash, host.bundleHash);
  } finally {
    host.process.kill();
  }
});
